static const char SOURCE[] =
    "# compiler.tainted: Tainted compiled to C, by Tainted.\n"
    "#\n"
    "# It hears a program from the world, line by line, and says a C program\n"
    "# that, built together with runtime/tainted.c, lives the same life.\n"
    "#\n"
    "# Every soul, kind and ritual becomes a unit: a table of its instructions,\n"
    "# which other souls look at to see whether this one is waiting for them, and\n"
    "# a step function that carries out the instruction the soul has come to.\n"
    "# Every expression becomes a C function, evaluated left to right.\n"
    "#\n"
    "# A compiler forgets like anyone else. Everything that has to outlive more\n"
    "# than a few steps is written down in notes; only what a loop touches on\n"
    "# every turn is kept in memory.\n"
    "\n"
    "# ------------------------------------------------------------ what it says\n"
    "\n"
    "ritual out_head text\n"
    "    note \"hn\" = note \"hn\" + 1\n"
    "    note (\"h \" + note \"hn\") = text\n"
    "end\n"
    "\n"
    "ritual out_body text\n"
    "    note \"bn\" = note \"bn\" + 1\n"
    "    note (\"b \" + note \"bn\") = text\n"
    "end\n"
    "\n"
    "ritual out_fn text\n"
    "    note \"fn\" = note \"fn\" + 1\n"
    "    note (\"f \" + note \"fn\") = text\n"
    "end\n"
    "\n"
    "ritual out_ins text\n"
    "    note \"in\" = note \"in\" + 1\n"
    "    note (\"i \" + note \"in\") = text\n"
    "end\n"
    "\n"
    "ritual out_case text\n"
    "    note \"csn\" = note \"csn\" + 1\n"
    "    note (\"c \" + note \"csn\") = text\n"
    "end\n"
    "\n"
    "ritual fail message\n"
    "    cry \"tainted: line \" + note (\"ln \" + note \"cj\") + \": \" + message\n"
    "    goodbye with 1\n"
    "end\n"
    "\n"
    "ritual fail_plain message\n"
    "    cry \"tainted: \" + message\n"
    "    goodbye with 1\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------------- text\n"
    "\n"
    "# What a string literal means: one pass, left to right.\n"
    "ritual unescape raw\n"
    "    let made = \"\"\n"
    "    let i = 1\n"
    "    let n = length of raw\n"
    "    while i <= n\n"
    "        let c = part i i of raw\n"
    "        if c == \"\\\\\" and i < n\n"
    "            let d = part (i + 1) (i + 1) of raw\n"
    "            if d == \"n\"\n"
    "                c = \"\\n\"\n"
    "            else\n"
    "                if d == \"\\\"\" or d == \"\\\\\"\n"
    "                    c = d\n"
    "                else\n"
    "                    c = \"\\\\\" + d\n"
    "                end\n"
    "            end\n"
    "            i = i + 1\n"
    "        end\n"
    "        made = made + c\n"
    "        i = i + 1\n"
    "    end\n"
    "    give back made\n"
    "end\n"
    "\n"
    "# A string as C writes it.\n"
    "ritual cquote text\n"
    "    let made = \"\"\n"
    "    let i = 1\n"
    "    let n = length of text\n"
    "    while i <= n\n"
    "        let c = part i i of text\n"
    "        if c == \"\\\\\" or c == \"\\\"\" or c == \"\?\"\n"
    "            c = \"\\\\\" + c\n"
    "        end\n"
    "        if c == \"\\n\"\n"
    "            c = \"\\\\n\"\n"
    "        end\n"
    "        made = made + c\n"
    "        i = i + 1\n"
    "    end\n"
    "    give back made\n"
    "end\n"
    "\n"
    "ritual digit c\n"
    "    give back c >= \"0\" and c <= \"9\"\n"
    "end\n"
    "\n"
    "ritual letter c\n"
    "    give back (c >= \"a\" and c <= \"z\") or (c >= \"A\" and c <= \"Z\") or c == \"_\"\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------------ lexing\n"
    "\n"
    "ritual token what, value\n"
    "    note \"lxc\" = note \"lxc\" + 1\n"
    "    let j = note \"lines\" + 1\n"
    "    note (\"tk \" + j + \" \" + note \"lxc\") = what\n"
    "    note (\"tv \" + j + \" \" + note \"lxc\") = value\n"
    "end\n"
    "\n"
    "ritual lex_fail\n"
    "    cry \"tainted: line \" + note \"lxn\" + \": cannot read '\" + part (note \"lxp\") (note \"lxlen\") of note \"lxl\" + \"'\"\n"
    "    goodbye with 1\n"
    "end\n"
    "\n"
    "ritual lex_number\n"
    "    let p = note \"lxp\"\n"
    "    let q = p\n"
    "    perform digit with part q q of note \"lxl\" into more\n"
    "    while more and q <= note \"lxlen\"\n"
    "        q = q + 1\n"
    "        perform digit with part q q of note \"lxl\" into more\n"
    "    end\n"
    "    let digits = part (note \"lxp\") (q - 1) of note \"lxl\"\n"
    "    let value = digits\n"
    "    while length of value > 1 and part 1 1 of value == \"0\"\n"
    "        value = part 2 (length of value) of value\n"
    "    end\n"
    "    if length of value > 19 or (length of value == 19 and value > \"9223372036854775807\")\n"
    "        cry \"tainted: line \" + note \"lxn\" + \": \" + digits + \" is too large a number\"\n"
    "        goodbye with 1\n"
    "    end\n"
    "    perform token with \"num\", value\n"
    "    note \"lxp\" = q\n"
    "end\n"
    "\n"
    "ritual lex_string\n"
    "    let q = note \"lxp\" + 1\n"
    "    let n = note \"lxlen\"\n"
    "    let closed = 0\n"
    "    while q <= n and not closed\n"
    "        let c = part q q of note \"lxl\"\n"
    "        if c == \"\\\\\"\n"
    "            if q == n\n"
    "                perform lex_fail\n"
    "            end\n"
    "            q = q + 2\n"
    "        else\n"
    "            if c == \"\\\"\"\n"
    "                closed = 1\n"
    "            else\n"
    "                q = q + 1\n"
    "            end\n"
    "        end\n"
    "    end\n"
    "    if not closed\n"
    "        perform lex_fail\n"
    "    end\n"
    "    perform unescape with part (note \"lxp\" + 1) (q - 1) of note \"lxl\" into value\n"
    "    perform token with \"str\", value\n"
    "    note \"lxp\" = q + 1\n"
    "end\n"
    "\n"
    "ritual lex_name\n"
    "    let p = note \"lxp\"\n"
    "    let q = p + 1\n"
    "    let c = part q q of note \"lxl\"\n"
    "    perform letter with c into a\n"
    "    perform digit with c into b\n"
    "    while (a or b) and q <= note \"lxlen\"\n"
    "        q = q + 1\n"
    "        c = part q q of note \"lxl\"\n"
    "        perform letter with c into a\n"
    "        perform digit with c into b\n"
    "    end\n"
    "    perform token with \"id\", part (note \"lxp\") (q - 1) of note \"lxl\"\n"
    "    note \"lxp\" = q\n"
    "end\n"
    "\n"
    "ritual lex_one\n"
    "    let p = note \"lxp\"\n"
    "    let c = part p p of note \"lxl\"\n"
    "    if c == \" \" or c == \"	\"\n"
    "        note \"lxp\" = p + 1\n"
    "        give back 0\n"
    "    end\n"
    "    if c == \"#\"\n"
    "        note \"lxp\" = note \"lxlen\" + 1\n"
    "        give back 0\n"
    "    end\n"
    "    perform digit with c into isdigit\n"
    "    if isdigit\n"
    "        perform lex_number\n"
    "        give back 0\n"
    "    end\n"
    "    if c == \"\\\"\"\n"
    "        perform lex_string\n"
    "        give back 0\n"
    "    end\n"
    "    perform letter with c into isletter\n"
    "    if isletter\n"
    "        perform lex_name\n"
    "        give back 0\n"
    "    end\n"
    "    let two = part p (p + 1) of note \"lxl\"\n"
    "    if two == \"==\" or two == \"!=\" or two == \"<=\" or two == \">=\"\n"
    "        perform token with \"op\", two\n"
    "        note \"lxp\" = p + 2\n"
    "        give back 0\n"
    "    end\n"
    "    if place of c in \"- + * / % < > = ( ) ,\" > 0\n"
    "        perform token with \"op\", c\n"
    "        note \"lxp\" = p + 1\n"
    "        give back 0\n"
    "    end\n"
    "    perform lex_fail\n"
    "end\n"
    "\n"
    "ritual lex line, n\n"
    "    note \"lxl\" = line\n"
    "    note \"lxn\" = n\n"
    "    note \"lxc\" = 0\n"
    "    note \"lxp\" = 1\n"
    "    note \"lxlen\" = length of line\n"
    "    while note \"lxp\" <= note \"lxlen\"\n"
    "        perform lex_one\n"
    "    end\n"
    "    if note \"lxc\" > 0\n"
    "        note \"lines\" = note \"lines\" + 1\n"
    "        note (\"ln \" + note \"lines\") = note \"lxn\"\n"
    "        note (\"nt \" + note \"lines\") = note \"lxc\"\n"
    "    end\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------------ reading\n"
    "\n"
    "ritual open_line j\n"
    "    note \"cj\" = j\n"
    "    note \"ck\" = 1\n"
    "    note \"cn\" = note (\"nt \" + j)\n"
    "end\n"
    "\n"
    "ritual peek_kind\n"
    "    if note \"ck\" > note \"cn\"\n"
    "        give back \"\"\n"
    "    end\n"
    "    give back note (\"tk \" + note \"cj\" + \" \" + note \"ck\")\n"
    "end\n"
    "\n"
    "ritual peek_value\n"
    "    if note \"ck\" > note \"cn\"\n"
    "        give back \"\"\n"
    "    end\n"
    "    give back note (\"tv \" + note \"cj\" + \" \" + note \"ck\")\n"
    "end\n"
    "\n"
    "ritual take\n"
    "    if note \"ck\" > note \"cn\"\n"
    "        perform fail with \"the line ends too early\"\n"
    "    end\n"
    "    let k = note \"ck\"\n"
    "    note \"ck\" = k + 1\n"
    "    give back k\n"
    "end\n"
    "\n"
    "ritual kind_of k\n"
    "    give back note (\"tk \" + note \"cj\" + \" \" + k)\n"
    "end\n"
    "\n"
    "ritual value_of k\n"
    "    give back note (\"tv \" + note \"cj\" + \" \" + k)\n"
    "end\n"
    "\n"
    "ritual reserved v\n"
    "    give back place of v in note \"keywords\" > 0\n"
    "end\n"
    "\n"
    "ritual is_word w\n"
    "    perform peek_kind into pk\n"
    "    if pk == \"id\"\n"
    "        perform peek_value into pv\n"
    "        if pv == w\n"
    "            note \"ck\" = note \"ck\" + 1\n"
    "            give back 1\n"
    "        end\n"
    "    end\n"
    "    give back 0\n"
    "end\n"
    "\n"
    "ritual is_op o\n"
    "    perform peek_kind into pk\n"
    "    if pk == \"op\"\n"
    "        perform peek_value into pv\n"
    "        if pv == o\n"
    "            note \"ck\" = note \"ck\" + 1\n"
    "            give back 1\n"
    "        end\n"
    "    end\n"
    "    give back 0\n"
    "end\n"
    "\n"
    "ritual expect_word w\n"
    "    perform is_word with w into yes\n"
    "    if not yes\n"
    "        perform fail with \"expected '\" + w + \"'\"\n"
    "    end\n"
    "end\n"
    "\n"
    "ritual a_name\n"
    "    perform take into k\n"
    "    perform kind_of with k into kd\n"
    "    perform value_of with k into v\n"
    "    perform reserved with v into taken\n"
    "    if kd != \"id\" or taken\n"
    "        perform fail with \"expected a name, got '\" + v + \"'\"\n"
    "    end\n"
    "    give back v\n"
    "end\n"
    "\n"
    "ritual line_done\n"
    "    if note \"ck\" <= note \"cn\"\n"
    "        perform value_of with note \"ck\" into v\n"
    "        perform fail with \"unexpected '\" + v + \"'\"\n"
    "    end\n"
    "end\n"
    "\n"
    "# ---------------------------------------------------------------- variables\n"
    "\n"
    "ritual slot_of name\n"
    "    let list = note (\"sl \" + note \"u\")\n"
    "    let at = place of name in list\n"
    "    if at > 0\n"
    "        give back at - 1\n"
    "    end\n"
    "    note (\"sl \" + note \"u\") = list + \" \" + name\n"
    "    note (\"sc \" + note \"u\") = note (\"sc \" + note \"u\") + 1\n"
    "    give back note (\"sc \" + note \"u\") - 1\n"
    "end\n"
    "\n"
    "# -------------------------------------------------------------- expressions\n"
    "\n"
    "ritual tmp code\n"
    "    note \"tn\" = note \"tn\" + 1\n"
    "    let t = \"t\" + note \"tn\"\n"
    "    perform out_fn with \"    Value \" + t + \" = \" + code + \";\"\n"
    "    give back t\n"
    "end\n"
    "\n"
    "ritual e_target\n"
    "    perform is_word with \"soul\" into computed\n"
    "    if computed\n"
    "        perform expect_word with \"named\"\n"
    "        perform e_unary into t\n"
    "        give back t\n"
    "    end\n"
    "    perform a_name into name\n"
    "    perform tmp with \"t_cstr(\\\"\" + name + \"\\\")\" into t\n"
    "    give back t\n"
    "end\n"
    "\n"
    "ritual e_primary\n"
    "    perform take into k\n"
    "    perform kind_of with k into kd\n"
    "    perform value_of with k into v\n"
    "    if kd == \"num\"\n"
    "        perform tmp with \"t_int(\" + v + \"LL)\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if kd == \"str\"\n"
    "        perform cquote with v into q\n"
    "        perform tmp with \"t_cstr(\\\"\" + q + \"\\\")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if kd == \"op\" and v == \"(\"\n"
    "        perform e_or into t\n"
    "        perform is_op with \")\" into closed\n"
    "        if not closed\n"
    "            perform fail with \"expected ')'\"\n"
    "        end\n"
    "        give back t\n"
    "    end\n"
    "    if kd != \"id\"\n"
    "        perform fail with \"unexpected '\" + v + \"'\"\n"
    "    end\n"
    "    if v == \"trust\" or v == \"intimacy\" or v == \"passion\" or v == \"commitment\"\n"
    "        let which = \"R_COMMITMENT\"\n"
    "        if v == \"trust\"\n"
    "            which = \"R_TRUST\"\n"
    "        end\n"
    "        if v == \"intimacy\"\n"
    "            which = \"R_INTIMACY\"\n"
    "        end\n"
    "        if v == \"passion\"\n"
    "            which = \"R_PASSION\"\n"
    "        end\n"
    "        perform e_target into who\n"
    "        perform tmp with \"t_rel(w, s, \" + which + \", \" + who + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"afraid\"\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_target into who\n"
    "        perform tmp with \"t_afraid(w, s, \" + who + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"bond\"\n"
    "        perform expect_word with \"with\"\n"
    "        perform e_target into who\n"
    "        perform tmp with \"t_bond(w, s, \" + who + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"scars\"\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_target into who\n"
    "        perform tmp with \"t_scars(w, s, \" + who + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"scar\"\n"
    "        perform e_unary into idx\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_target into who\n"
    "        perform tmp with \"t_scar(w, s, \" + idx + \", \" + who + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"me\"\n"
    "        perform tmp with \"t_me(w, s)\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"note\"\n"
    "        perform e_unary into key\n"
    "        perform tmp with \"t_note_get(w, s, \" + key + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"word\"\n"
    "        perform e_unary into idx\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_unary into text\n"
    "        perform tmp with \"t_word(w, \" + idx + \", \" + text + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"words\" or v == \"number\"\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_unary into text\n"
    "        perform tmp with \"t_\" + v + \"(w, \" + text + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"place\"\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_unary into x\n"
    "        perform expect_word with \"in\"\n"
    "        perform e_unary into text\n"
    "        perform tmp with \"t_place(w, \" + x + \", \" + text + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"runs\"\n"
    "        perform tmp with \"t_runs(w)\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"length\"\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_unary into text\n"
    "        perform tmp with \"t_length(w, \" + text + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    if v == \"part\"\n"
    "        perform e_unary into a\n"
    "        perform e_unary into b\n"
    "        perform expect_word with \"of\"\n"
    "        perform e_unary into text\n"
    "        perform tmp with \"t_part(w, \" + a + \", \" + b + \", \" + text + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    perform reserved with v into taken\n"
    "    if taken\n"
    "        perform fail with \"unexpected '\" + v + \"'\"\n"
    "    end\n"
    "    perform slot_of with v into slot\n"
    "    perform tmp with \"t_var(w, s, \" + slot + \")\" into t\n"
    "    give back t\n"
    "end\n"
    "\n"
    "ritual e_unary\n"
    "    perform is_op with \"-\" into negative\n"
    "    if negative\n"
    "        perform e_unary into x\n"
    "        perform tmp with \"t_neg(w, \" + x + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    perform e_primary into t\n"
    "    give back t\n"
    "end\n"
    "\n"
    "ritual e_mul\n"
    "    perform e_unary into a\n"
    "    let going = 1\n"
    "    while going\n"
    "        let op = \"\"\n"
    "        perform is_op with \"*\" into yes\n"
    "        if yes\n"
    "            op = \"B_MUL\"\n"
    "        else\n"
    "            perform is_op with \"/\" into yes\n"
    "            if yes\n"
    "                op = \"B_DIV\"\n"
    "            else\n"
    "                perform is_op with \"%\" into yes\n"
    "                if yes\n"
    "                    op = \"B_MOD\"\n"
    "                end\n"
    "            end\n"
    "        end\n"
    "        going = op != \"\"\n"
    "        if going\n"
    "            perform e_unary into b\n"
    "            perform tmp with \"t_bin(w, \" + op + \", \" + a + \", \" + b + \")\" into a\n"
    "        end\n"
    "    end\n"
    "    give back a\n"
    "end\n"
    "\n"
    "ritual e_add\n"
    "    perform e_mul into a\n"
    "    let going = 1\n"
    "    while going\n"
    "        let op = \"\"\n"
    "        perform is_op with \"+\" into yes\n"
    "        if yes\n"
    "            op = \"B_ADD\"\n"
    "        else\n"
    "            perform is_op with \"-\" into yes\n"
    "            if yes\n"
    "                op = \"B_SUB\"\n"
    "            end\n"
    "        end\n"
    "        going = op != \"\"\n"
    "        if going\n"
    "            perform e_mul into b\n"
    "            perform tmp with \"t_bin(w, \" + op + \", \" + a + \", \" + b + \")\" into a\n"
    "        end\n"
    "    end\n"
    "    give back a\n"
    "end\n"
    "\n"
    "ritual e_cmp\n"
    "    perform e_add into a\n"
    "    let ops = \"== != <= >= < >\"\n"
    "    let names = \"B_EQ B_NE B_LE B_GE B_LT B_GT\"\n"
    "    let i = 1\n"
    "    while i <= 6\n"
    "        perform is_op with word i of ops into yes\n"
    "        if yes\n"
    "            perform e_add into b\n"
    "            perform tmp with \"t_bin(w, \" + word i of names + \", \" + a + \", \" + b + \")\" into t\n"
    "            give back t\n"
    "        end\n"
    "        i = i + 1\n"
    "        recall a ops names\n"
    "    end\n"
    "    give back a\n"
    "end\n"
    "\n"
    "ritual e_not\n"
    "    perform is_word with \"not\" into negated\n"
    "    if negated\n"
    "        perform e_not into x\n"
    "        perform tmp with \"t_not(\" + x + \")\" into t\n"
    "        give back t\n"
    "    end\n"
    "    perform e_cmp into t\n"
    "    give back t\n"
    "end\n"
    "\n"
    "# `and` and `or` look at their right side only when the left one has not\n"
    "# already decided.\n"
    "ritual e_and\n"
    "    perform e_not into a\n"
    "    let going = 1\n"
    "    while going\n"
    "        perform is_word with \"and\" into going\n"
    "        if going\n"
    "            perform tmp with \"t_int(0)\" into both\n"
    "            perform out_fn with \"    if (t_truthy(\" + a + \")) {\"\n"
    "            perform e_not into b\n"
    "            perform out_fn with \"    \" + both + \" = t_int(t_truthy(\" + b + \"));\"\n"
    "            perform out_fn with \"    }\"\n"
    "            a = both\n"
    "        end\n"
    "    end\n"
    "    give back a\n"
    "end\n"
    "\n"
    "ritual e_or\n"
    "    perform e_and into a\n"
    "    let going = 1\n"
    "    while going\n"
    "        perform is_word with \"or\" into going\n"
    "        if going\n"
    "            perform tmp with \"t_int(1)\" into either\n"
    "            perform out_fn with \"    if (!t_truthy(\" + a + \")) {\"\n"
    "            perform e_and into b\n"
    "            perform out_fn with \"    \" + either + \" = t_int(t_truthy(\" + b + \"));\"\n"
    "            perform out_fn with \"    }\"\n"
    "            a = either\n"
    "        end\n"
    "    end\n"
    "    give back a\n"
    "end\n"
    "\n"
    "# An expression, or a soul, or a unary operand, as a C function of its own.\n"
    "\n"
    "ritual begin_fn\n"
    "    note \"fn\" = 0\n"
    "    note \"tn\" = 0\n"
    "end\n"
    "\n"
    "ritual end_fn result\n"
    "    note \"en\" = note \"en\" + 1\n"
    "    let name = \"E\" + note \"en\"\n"
    "    perform out_body with \"static Value \" + name + \"(World *w, Soul *s) {\"\n"
    "    perform out_body with \"    (void)w; (void)s;\"\n"
    "    let i = 1\n"
    "    while i <= note \"fn\"\n"
    "        perform out_body with note (\"f \" + i)\n"
    "        i = i + 1\n"
    "        recall name result\n"
    "    end\n"
    "    perform out_body with \"    return \" + result + \";\"\n"
    "    perform out_body with \"}\"\n"
    "    give back name\n"
    "end\n"
    "\n"
    "ritual expr_fn\n"
    "    perform begin_fn\n"
    "    perform e_or into t\n"
    "    perform end_fn with t into name\n"
    "    give back name\n"
    "end\n"
    "\n"
    "ritual unary_fn\n"
    "    perform begin_fn\n"
    "    perform e_unary into t\n"
    "    perform end_fn with t into name\n"
    "    give back name\n"
    "end\n"
    "\n"
    "ritual target_fn\n"
    "    perform begin_fn\n"
    "    perform e_target into t\n"
    "    perform end_fn with t into name\n"
    "    give back name\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------- instructions\n"
    "\n"
    "ritual add_ins op, extra, code\n"
    "    let pc = note \"pc\"\n"
    "    perform out_ins with \"    {.op=\" + op + \", .line=\" + note \"hl\" + extra + \"},\"\n"
    "    perform out_case with \"    case \" + pc + \": \" + code\n"
    "    note \"pc\" = pc + 1\n"
    "end\n"
    "\n"
    "ritual here\n"
    "    give back \"&I\" + note \"u\" + \"[\" + note \"pc\" + \"]\"\n"
    "end\n"
    "\n"
    "ritual plain op, call\n"
    "    perform here into at\n"
    "    perform add_ins with op, note \"none\", \"return \" + call + \"(w, s, \" + at + \");\"\n"
    "end\n"
    "\n"
    "ritual with_value op, call\n"
    "    perform expr_fn into e\n"
    "    perform add_ins with op, \", .a=\" + e + note \"none\", \"return \" + call + \"(w, s, \" + e + \"(w, s));\"\n"
    "end\n"
    "\n"
    "ritual feeling op\n"
    "    perform target_fn into t\n"
    "    perform here into at\n"
    "    perform add_ins with op, \", .mode=TO_NAMED, .target=\" + t + note \"none\", \"return t_feel(w, s, \" + at + \");\"\n"
    "end\n"
    "\n"
    "ritual label\n"
    "    note \"labels\" = note \"labels\" + 1\n"
    "    give back \"J\" + note \"u\" + \"_\" + note \"labels\"\n"
    "end\n"
    "\n"
    "ritual define name, value\n"
    "    perform out_head with \"#define \" + name + \" \" + value\n"
    "end\n"
    "\n"
    "ritual jz_to target\n"
    "    perform expr_fn into e\n"
    "    perform add_ins with \"OP_JZ\", \", .a=\" + e + note \"none\", \"return t_jz(w, s, \" + e + \"(w, s), \" + target + \");\"\n"
    "end\n"
    "\n"
    "ritual jmp_to target\n"
    "    perform add_ins with \"OP_JMP\", note \"none\", \"return t_jmp(w, s, \" + target + \");\"\n"
    "end\n"
    "\n"
    "ritual uses list, name\n"
    "    if place of name in note list == 0\n"
    "        note list = note list + \" \" + name\n"
    "    end\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------------- blocks\n"
    "\n"
    "ritual at ends\n"
    "    if note \"j\" > note \"lines\"\n"
    "        perform fail_plain with \"the program ends before an 'end'\"\n"
    "    end\n"
    "    let j = note \"j\"\n"
    "    if note (\"nt \" + j) != 1\n"
    "        give back 0\n"
    "    end\n"
    "    if note (\"tk \" + j + \" 1\") != \"id\"\n"
    "        give back 0\n"
    "    end\n"
    "    give back place of note (\"tv \" + j + \" 1\") in ends > 0\n"
    "end\n"
    "\n"
    "ritual block ends\n"
    "    perform at with ends into stop\n"
    "    while not stop\n"
    "        perform statement\n"
    "        perform at with ends into stop\n"
    "    end\n"
    "end\n"
    "\n"
    "ritual conditional head, line, top\n"
    "    let id = 0\n"
    "    perform label into id\n"
    "    perform jz_to with id + \"e\"\n"
    "    perform line_done\n"
    "    perform block with \"else end\"\n"
    "    perform at with \"else\" into other\n"
    "    if head == \"while\"\n"
    "        if other\n"
    "            perform open_line with line\n"
    "            perform fail with \"a while has no else\"\n"
    "        end\n"
    "        note \"hl\" = note (\"ln \" + line)\n"
    "        perform jmp_to with top\n"
    "        perform define with id + \"e\", note \"pc\"\n"
    "        note \"j\" = note \"j\" + 1\n"
    "        give back 0\n"
    "    end\n"
    "    if other\n"
    "        note \"hl\" = note (\"ln \" + line)\n"
    "        perform jmp_to with id + \"x\"\n"
    "        perform define with id + \"e\", note \"pc\"\n"
    "        note \"j\" = note \"j\" + 1\n"
    "        perform block with \"end\"\n"
    "        perform define with id + \"x\", note \"pc\"\n"
    "    else\n"
    "        perform define with id + \"e\", note \"pc\"\n"
    "    end\n"
    "    note \"j\" = note \"j\" + 1\n"
    "end\n"
    "\n"
    "# --------------------------------------------------------------- statements\n"
    "\n"
    "ritual statement\n"
    "    let j = note \"j\"\n"
    "    note \"j\" = j + 1\n"
    "    perform open_line with j\n"
    "    note \"hl\" = note (\"ln \" + j)\n"
    "    perform peek_kind into kd\n"
    "    perform peek_value into head\n"
    "    if kd != \"id\"\n"
    "        perform fail with \"a line cannot start with '\" + head + \"'\"\n"
    "    end\n"
    "    perform reserved with head into isreserved\n"
    "    if not isreserved\n"
    "        perform a_name into name\n"
    "        perform is_op with \"=\" into eq\n"
    "        if not eq\n"
    "            perform fail with \"'\" + name + \"' is not something a soul can do\"\n"
    "        end\n"
    "        perform slot_of with name into slot\n"
    "        perform expr_fn into e\n"
    "        perform add_ins with \"OP_LET\", \", .a=\" + e + \", .var=\" + slot + \", .var2=-1, .unit=-1\", \"return t_let(w, s, \" + slot + \", \" + e + \"(w, s));\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    perform take into skipped\n"
    "    perform statement_of with head, j\n"
    "end\n"
    "\n"
    "ritual statement_of head, j\n"
    "    if head == \"let\"\n"
    "        perform a_name into name\n"
    "        perform is_op with \"=\" into eq\n"
    "        if not eq\n"
    "            perform fail with \"expected '='\"\n"
    "        end\n"
    "        perform slot_of with name into slot\n"
    "        perform expr_fn into e\n"
    "        perform add_ins with \"OP_LET\", \", .a=\" + e + \", .var=\" + slot + \", .var2=-1, .unit=-1\", \"return t_let(w, s, \" + slot + \", \" + e + \"(w, s));\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"say\"\n"
    "        perform with_value with \"OP_SAY\", \"t_say\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"cry\"\n"
    "        perform with_value with \"OP_CRY\", \"t_cry\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"meet\"\n"
    "        perform is_word with \"anyone\" into stranger\n"
    "        perform here into at\n"
    "        if stranger\n"
    "            perform expect_word with \"as\"\n"
    "            perform a_name into name\n"
    "            perform slot_of with name into slot\n"
    "            perform add_ins with \"OP_MEET\", \", .mode=TO_ANYONE, .var=\" + slot + \", .var2=-1, .unit=-1\", \"return t_meet(w, s, \" + at + \");\"\n"
    "        else\n"
    "            perform target_fn into t\n"
    "            perform add_ins with \"OP_MEET\", \", .mode=TO_NAMED, .target=\" + t + note \"none\", \"return t_meet(w, s, \" + at + \");\"\n"
    "        end\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"tell\" or head == \"confide\"\n"
    "        perform target_fn into t\n"
    "        perform expr_fn into e\n"
    "        perform here into at\n"
    "        let op = \"OP_TELL\"\n"
    "        if head == \"confide\"\n"
    "            op = \"OP_CONFIDE\"\n"
    "        end\n"
    "        perform add_ins with op, \", .mode=TO_NAMED, .target=\" + t + \", .a=\" + e + note \"none\", \"return t_tell(w, s, \" + at + \");\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"note\"\n"
    "        perform unary_fn into key\n"
    "        perform is_op with \"=\" into eq\n"
    "        if not eq\n"
    "            perform fail with \"expected '='\"\n"
    "        end\n"
    "        perform expr_fn into e\n"
    "        perform add_ins with \"OP_NOTE\", \", .a=\" + e + \", .b=\" + key + note \"none\", \"{ Value v = \" + e + \"(w, s); Value k = \" + key + \"(w, s); return t_note(w, s, k, v); }\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"bring\"\n"
    "        perform a_name into sort\n"
    "        perform expect_word with \"named\"\n"
    "        perform expr_fn into e\n"
    "        perform uses with \"kinds used\", sort\n"
    "        perform here into at\n"
    "        perform add_ins with \"OP_BRING\", \", .a=\" + e + \", .var=-1, .var2=-1, .unit=K_\" + sort + \", .name=\\\"\" + sort + \"\\\"\", \"return t_bring(w, s, \" + at + \");\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"hear\"\n"
    "        let mode = \"TO_NAMED\"\n"
    "        let t = \"0\"\n"
    "        perform is_word with \"anyone\" into stranger\n"
    "        if stranger\n"
    "            mode = \"TO_ANYONE\"\n"
    "        else\n"
    "            perform is_word with \"world\" into outside\n"
    "            if outside\n"
    "                mode = \"TO_WORLD\"\n"
    "            else\n"
    "                perform target_fn into t\n"
    "            end\n"
    "        end\n"
    "        perform expect_word with \"into\"\n"
    "        perform a_name into name\n"
    "        perform slot_of with name into slot\n"
    "        let speaker = -1\n"
    "        perform is_word with \"from\" into asks\n"
    "        if asks\n"
    "            perform a_name into who\n"
    "            perform slot_of with who into speaker\n"
    "            if mode != \"TO_ANYONE\"\n"
    "                perform fail with \"only 'hear anyone' needs to ask who it was\"\n"
    "            end\n"
    "        end\n"
    "        perform here into at\n"
    "        perform add_ins with \"OP_HEAR\", \", .mode=\" + mode + \", .target=\" + t + \", .var=\" + slot + \", .var2=\" + speaker + \", .unit=-1\", \"return t_hear(w, s, \" + at + \");\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"warm\" or head == \"cool\"\n"
    "        perform expect_word with \"to\"\n"
    "        let op = \"OP_WARM\"\n"
    "        if head == \"cool\"\n"
    "            op = \"OP_COOL\"\n"
    "        end\n"
    "        perform feeling with op\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"give\"\n"
    "        perform is_word with \"back\" into returning\n"
    "        if returning\n"
    "            perform with_value with \"OP_GIVEBACK\", \"t_giveback\"\n"
    "        else\n"
    "            perform expect_word with \"heart\"\n"
    "            perform expect_word with \"to\"\n"
    "            perform feeling with \"OP_GIVE\"\n"
    "        end\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"perform\"\n"
    "        perform a_name into name\n"
    "        let args = \"\"\n"
    "        let count = 0\n"
    "        perform is_word with \"with\" into given\n"
    "        if given\n"
    "            perform expr_fn into e\n"
    "            args = e\n"
    "            count = 1\n"
    "            perform is_op with \",\" into more\n"
    "            while more\n"
    "                perform expr_fn into e\n"
    "                args = args + \", \" + e\n"
    "                count = count + 1\n"
    "                perform is_op with \",\" into more\n"
    "            end\n"
    "        end\n"
    "        let receiver = -1\n"
    "        perform is_word with \"into\" into keeps\n"
    "        if keeps\n"
    "            perform a_name into kept\n"
    "            perform slot_of with kept into receiver\n"
    "        end\n"
    "        perform uses with \"rituals used\", name\n"
    "        let arrays = \"\"\n"
    "        if count > 0\n"
    "            let array = \"A\" + note \"u\" + \"_\" + note \"pc\"\n"
    "            perform out_body with \"static const Expr \" + array + \"[] = {\" + args + \"};\"\n"
    "            arrays = \", .nargs=\" + count + \", .args=\" + array\n"
    "        end\n"
    "        perform here into at\n"
    "        perform add_ins with \"OP_PERFORM\", \", .var=\" + receiver + \", .var2=-1, .unit=RT_\" + name + \", .name=\\\"\" + name + \"\\\"\" + arrays, \"return t_perform(w, s, \" + at + \");\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"promise\"\n"
    "        perform feeling with \"OP_PROMISE\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"wound\"\n"
    "        perform feeling with \"OP_WOUND\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"forgive\"\n"
    "        perform feeling with \"OP_FORGIVE\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"leave\"\n"
    "        perform feeling with \"OP_LEAVE\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"wait\"\n"
    "        perform is_word with \"for\" into waits\n"
    "        if waits\n"
    "            perform expect_word with \"silence\"\n"
    "            perform add_ins with \"OP_SILENCE\", note \"none\", \"return t_silence(w, s);\"\n"
    "        else\n"
    "            perform add_ins with \"OP_WAIT\", note \"none\", \"return t_wait(w, s);\"\n"
    "        end\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"recall\"\n"
    "        perform a_name into name\n"
    "        perform slot_of with name into slot\n"
    "        let list = \"\" + slot\n"
    "        let count = 1\n"
    "        perform peek_kind into pk\n"
    "        while pk != \"\"\n"
    "            perform a_name into name\n"
    "            perform slot_of with name into slot\n"
    "            list = list + \", \" + slot\n"
    "            count = count + 1\n"
    "            perform peek_kind into pk\n"
    "        end\n"
    "        let array = \"V\" + note \"u\" + \"_\" + note \"pc\"\n"
    "        perform out_body with \"static const int \" + array + \"[] = {\" + list + \"};\"\n"
    "        perform here into at\n"
    "        perform add_ins with \"OP_RECALL\", note \"none\" + \", .nvars=\" + count + \", .vars=\" + array, \"return t_recall(w, s, \" + at + \");\"\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"goodbye\"\n"
    "        perform is_word with \"with\" into ending\n"
    "        if ending\n"
    "            perform with_value with \"OP_GOODBYE\", \"t_goodbye_with\"\n"
    "        else\n"
    "            perform add_ins with \"OP_GOODBYE\", note \"none\", \"return t_goodbye(w, s);\"\n"
    "        end\n"
    "        perform line_done\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"mark\"\n"
    "        perform a_name into moment\n"
    "        perform line_done\n"
    "        let u = note \"u\"\n"
    "        if place of moment in note (\"marks \" + u) > 0\n"
    "            if note (\"merr \" + u) == \"\"\n"
    "                note (\"merr \" + u) = \"line \" + note \"hl\" + \": \" + note \"uname\" + \" already has a moment called \" + moment\n"
    "            end\n"
    "        else\n"
    "            note (\"marks \" + u) = note (\"marks \" + u) + \" \" + moment\n"
    "            perform define with \"M\" + u + \"_\" + moment, note \"pc\"\n"
    "        end\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"return\"\n"
    "        perform expect_word with \"to\"\n"
    "        perform a_name into moment\n"
    "        perform line_done\n"
    "        let u = note \"u\"\n"
    "        note (\"rn \" + u) = note (\"rn \" + u) + 1\n"
    "        note (\"rname \" + u + \" \" + note (\"rn \" + u)) = moment\n"
    "        note (\"rline \" + u + \" \" + note (\"rn \" + u)) = note \"hl\"\n"
    "        perform jmp_to with \"M\" + u + \"_\" + moment\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"if\"\n"
    "        perform conditional with \"if\", j, 0\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"while\"\n"
    "        perform conditional with \"while\", j, note \"pc\"\n"
    "        give back 0\n"
    "    end\n"
    "    if head == \"first\"\n"
    "        perform expect_word with \"time\"\n"
    "        perform line_done\n"
    "        let id = 0\n"
    "        perform label into id\n"
    "        perform add_ins with \"OP_FIRST\", note \"none\", \"return t_first(w, s, \" + id + \"e);\"\n"
    "        perform block with \"end\"\n"
    "        perform define with id + \"e\", note \"pc\"\n"
    "        note \"j\" = note \"j\" + 1\n"
    "        give back 0\n"
    "    end\n"
    "    perform fail with \"'\" + head + \"' cannot start a line\"\n"
    "end\n"
    "\n"
    "# ------------------------------------------------------------- declarations\n"
    "\n"
    "ritual finish_unit\n"
    "    let u = note \"u\"\n"
    "    let i = 1\n"
    "    while i <= note (\"rn \" + u)\n"
    "        let moment = note (\"rname \" + u + \" \" + i)\n"
    "        if place of moment in note (\"marks \" + u) == 0\n"
    "            if note (\"merr \" + u) == \"\"\n"
    "                note (\"merr \" + u) = \"line \" + note (\"rline \" + u + \" \" + i) + \": \" + note \"uname\" + \" has no moment called \" + moment + \" to return to\"\n"
    "            end\n"
    "            perform define with \"M\" + u + \"_\" + moment, 0\n"
    "            note (\"marks \" + u) = note (\"marks \" + u) + \" \" + moment\n"
    "        end\n"
    "        i = i + 1\n"
    "    end\n"
    "    let names = \"\"\n"
    "    let list = note (\"sl \" + note \"u\")\n"
    "    i = 1\n"
    "    while i <= words of list\n"
    "        names = names + \"\\\"\" + word i of list + \"\\\", \"\n"
    "        i = i + 1\n"
    "    end\n"
    "    perform out_body with \"static const char *const N\" + note \"u\" + \"[] = {\" + names + \"0};\"\n"
    "    perform out_body with \"static const int P\" + note \"u\" + \"[] = {\" + note \"params\" + \"-1};\"\n"
    "    perform out_body with \"static const Ins I\" + note \"u\" + \"[] = {\"\n"
    "    i = 1\n"
    "    while i <= note \"in\"\n"
    "        perform out_body with note (\"i \" + i)\n"
    "        i = i + 1\n"
    "    end\n"
    "    perform out_body with \"    {.op=OP_WAIT, .var=-1, .var2=-1, .unit=-1}\"\n"
    "    perform out_body with \"};\"\n"
    "    perform out_body with \"static int S\" + note \"u\" + \"(World *w, Soul *s) {\"\n"
    "    perform out_body with \"    (void)w;\"\n"
    "    perform out_body with \"    switch (t_pc(s)) {\"\n"
    "    i = 1\n"
    "    while i <= note \"csn\"\n"
    "        perform out_body with note (\"c \" + i)\n"
    "        i = i + 1\n"
    "    end\n"
    "    perform out_body with \"    }\"\n"
    "    perform out_body with \"    return 0;\"\n"
    "    perform out_body with \"}\"\n"
    "    let decl = \"D_SOUL\"\n"
    "    if note \"udecl\" == \"kind\"\n"
    "        decl = \"D_KIND\"\n"
    "    end\n"
    "    if note \"udecl\" == \"ritual\"\n"
    "        decl = \"D_RITUAL\"\n"
    "    end\n"
    "    let u2 = note \"u\"\n"
    "    note (\"unit \" + u2) = \"    {.decl=\" + decl + \", .name=\\\"\" + note \"uname\" + \"\\\", .nins=\" + note \"pc\" + \", .ins=I\" + u2 + \", .nslots=\" + note (\"sc \" + u2) + \", .slots=N\" + u2 + \", .nparams=\" + note \"nparams\" + \", .params=P\" + u2 + \", .step=S\" + u2 + \"},\"\n"
    "end\n"
    "\n"
    "ritual declaration\n"
    "    let j = note \"j\"\n"
    "    perform open_line with j\n"
    "    note \"hl\" = note (\"ln \" + j)\n"
    "    let decl = \"\"\n"
    "    perform is_word with \"soul\" into yes\n"
    "    if yes\n"
    "        decl = \"soul\"\n"
    "    else\n"
    "        perform is_word with \"kind\" into yes\n"
    "        if yes\n"
    "            decl = \"kind\"\n"
    "        else\n"
    "            perform is_word with \"ritual\" into yes\n"
    "            if yes\n"
    "                decl = \"ritual\"\n"
    "            end\n"
    "        end\n"
    "    end\n"
    "    if decl == \"\"\n"
    "        perform fail with \"everything must belong to a soul, a kind of soul or a ritual\"\n"
    "    end\n"
    "    perform a_name into name\n"
    "    let u = note \"units\"\n"
    "    note \"units\" = u + 1\n"
    "    note \"u\" = u\n"
    "    note \"uname\" = name\n"
    "    note \"udecl\" = decl\n"
    "    note \"pc\" = 0\n"
    "    note \"in\" = 0\n"
    "    note \"csn\" = 0\n"
    "    note \"labels\" = 0\n"
    "    note (\"sl \" + u) = \"\"\n"
    "    note (\"sc \" + u) = 0\n"
    "    note (\"marks \" + u) = \"\"\n"
    "    note (\"merr \" + u) = \"\"\n"
    "    note (\"rn \" + u) = 0\n"
    "    note \"params\" = \"\"\n"
    "    note \"nparams\" = 0\n"
    "    if decl == \"ritual\"\n"
    "        perform peek_kind into pk\n"
    "        while pk != \"\"\n"
    "            perform a_name into param\n"
    "            perform slot_of with param into slot\n"
    "            note \"params\" = note \"params\" + slot + \", \"\n"
    "            note \"nparams\" = note \"nparams\" + 1\n"
    "            perform is_op with \",\" into comma\n"
    "            perform peek_kind into pk\n"
    "            recall j decl name u\n"
    "        end\n"
    "    end\n"
    "    perform line_done\n"
    "    note \"j\" = j + 1\n"
    "    perform block with \"end\"\n"
    "    note \"j\" = note \"j\" + 1\n"
    "    if place of (decl + \":\" + name) in note \"declared\" > 0\n"
    "        perform open_line with j\n"
    "        perform fail with \"there is already a \" + decl + \" called \" + name\n"
    "    end\n"
    "    note \"declared\" = note \"declared\" + \" \" + decl + \":\" + name\n"
    "    if decl == \"soul\"\n"
    "        note \"souls\" = note \"souls\" + 1\n"
    "    end\n"
    "    if decl == \"kind\"\n"
    "        note (\"K \" + name) = u\n"
    "    end\n"
    "    if decl == \"ritual\"\n"
    "        note (\"RT \" + name) = u\n"
    "    end\n"
    "    perform finish_unit\n"
    "end\n"
    "\n"
    "ritual define_uses list, prefix, sort\n"
    "    let names = note list\n"
    "    let i = 1\n"
    "    while i <= words of names\n"
    "        let name = word i of names\n"
    "        let value = -1\n"
    "        if place of (sort + \":\" + name) in note \"declared\" > 0\n"
    "            value = note (prefix + \" \" + name)\n"
    "        end\n"
    "        perform define with prefix + \"_\" + name, value\n"
    "        i = i + 1\n"
    "        recall names list prefix sort\n"
    "    end\n"
    "end\n"
    "\n"
    "ritual say_all\n"
    "    let i = 1\n"
    "    while i <= note \"hn\"\n"
    "        say note (\"h \" + i)\n"
    "        i = i + 1\n"
    "    end\n"
    "    i = 1\n"
    "    while i <= note \"bn\"\n"
    "        say note (\"b \" + i)\n"
    "        i = i + 1\n"
    "    end\n"
    "end\n"
    "\n"
    "soul compiler\n"
    "    note \"keywords\" = \"soul end let say meet tell confide hear into anyone warm cool to promise give heart wound forgive leave wait mark return if else while first time goodbye and or not trust intimacy passion commitment bond with scars scar of runs afraid world recall length part me note word words place in number named kind bring from silence for as ritual perform back cry\"\n"
    "    note \"none\" = \", .var=-1, .var2=-1, .unit=-1\"\n"
    "    note \"hn\" = 0\n"
    "    note \"bn\" = 0\n"
    "    note \"en\" = 0\n"
    "    note \"lines\" = 0\n"
    "    note \"units\" = 0\n"
    "    note \"souls\" = 0\n"
    "    note \"declared\" = \"\"\n"
    "    note \"kinds used\" = \"\"\n"
    "    note \"rituals used\" = \"\"\n"
    "\n"
    "    note \"src\" = 0\n"
    "    hear world into line\n"
    "    while line != 0\n"
    "        note \"src\" = note \"src\" + 1\n"
    "        note (\"src \" + note \"src\") = line\n"
    "        hear world into line\n"
    "    end\n"
    "\n"
    "    note \"n\" = 1\n"
    "    while note \"n\" <= note \"src\"\n"
    "        perform lex with note (\"src \" + note \"n\"), note \"n\"\n"
    "        note \"n\" = note \"n\" + 1\n"
    "    end\n"
    "\n"
    "    note \"j\" = 1\n"
    "    while note \"j\" <= note \"lines\"\n"
    "        perform declaration\n"
    "    end\n"
    "    if note \"units\" == 0\n"
    "        perform fail_plain with \"a program needs at least one soul\"\n"
    "    end\n"
    "    note \"n\" = 0\n"
    "    while note \"n\" < note \"units\"\n"
    "        if note (\"merr \" + note \"n\") != \"\"\n"
    "            cry \"tainted: \" + note (\"merr \" + note \"n\")\n"
    "            goodbye with 1\n"
    "        end\n"
    "        note \"n\" = note \"n\" + 1\n"
    "    end\n"
    "    if note \"souls\" == 0\n"
    "        perform fail_plain with \"a program needs at least one soul\"\n"
    "    end\n"
    "\n"
    "    perform out_head with \"/* Compiled from Tainted by compiler.tainted. */\"\n"
    "    perform out_head with \"#include \\\"tainted.h\\\"\"\n"
    "    perform define_uses with \"kinds used\", \"K\", \"kind\"\n"
    "    perform define_uses with \"rituals used\", \"RT\", \"ritual\"\n"
    "\n"
    "    perform out_body with \"static const Unit UNITS[] = {\"\n"
    "    note \"n\" = 0\n"
    "    while note \"n\" < note \"units\"\n"
    "        perform out_body with note (\"unit \" + note \"n\")\n"
    "        note \"n\" = note \"n\" + 1\n"
    "    end\n"
    "    perform out_body with \"};\"\n"
    "    perform out_body with \"static const char SOURCE[] =\"\n"
    "    note \"n\" = 1\n"
    "    while note \"n\" <= note \"src\"\n"
    "        perform cquote with note (\"src \" + note \"n\") into quoted\n"
    "        perform out_body with \"    \\\"\" + quoted + \"\\\\n\\\"\"\n"
    "        note \"n\" = note \"n\" + 1\n"
    "    end\n"
    "    perform out_body with \"    \\\"\\\";\"\n"
    "    perform out_body with \"static const Program PROGRAM = {\" + note \"units\" + \", UNITS, SOURCE};\"\n"
    "    perform out_body with \"int main(int argc, char **argv) { return tainted_main(&PROGRAM, argc, argv); }\"\n"
    "    perform say_all\n"
    "end\n"
    "";
static const Program PROGRAM = {66, UNITS, SOURCE};
int main(int argc, char **argv) { return tainted_main(&PROGRAM, argc, argv); }
